#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

#define MAX_CONTAINERS 64
#define MAX_KEY_LEN 128
#define MAX_VAL_LEN 512
#define MAX_PROPS 32

typedef struct property {
    char key[MAX_KEY_LEN];
    char value[MAX_VAL_LEN];
} property_t;

typedef struct container_config {
    property_t props[MAX_PROPS];
    int prop_count;
    const struct container_config *prototype;
} container_config_t;

typedef struct {
    container_config_t *configs[MAX_CONTAINERS];
    int count;
    pthread_mutex_t lock;
    container_config_t base_template;
} orchestrator_t;

static orchestrator_t g_orch;

void init_orchestrator(void) {
    memset(&g_orch, 0, sizeof(orchestrator_t));
    pthread_mutex_init(&g_orch.lock, NULL);
    strcpy(g_orch.base_template.props[0].key, "network_mode");
    strcpy(g_orch.base_template.props[0].value, "bridge");
    strcpy(g_orch.base_template.props[1].key, "privileged");
    strcpy(g_orch.base_template.props[1].value, "false");
    strcpy(g_orch.base_template.props[2].key, "capabilities");
    strcpy(g_orch.base_template.props[2].value, "none");
    g_orch.base_template.prop_count = 3;
    g_orch.base_template.prototype = NULL;
}

const char* resolve_property(const container_config_t *cfg, const char *key) {
    if (!cfg) return NULL;
    for (int i = 0; i < cfg->prop_count; i++) {
        if (strcmp(cfg->props[i].key, key) == 0) {
            return cfg->props[i].value;
        }
    }
    return resolve_property(cfg->prototype, key);
}

int set_property(container_config_t *cfg, const char *key, const char *value) {
    if (!cfg || !key || !value) return -1;
    if (strlen(key) >= MAX_KEY_LEN || strlen(value) >= MAX_VAL_LEN) return -1;

    for (int i = 0; i < cfg->prop_count; i++) {
        if (strcmp(cfg->props[i].key, key) == 0) {
            strncpy(cfg->props[i].value, value, MAX_VAL_LEN - 1);
            cfg->props[i].value[MAX_VAL_LEN - 1] = '\0';
            return 0;
        }
    }
    if (cfg->prop_count >= MAX_PROPS) return -1;
    strncpy(cfg->props[cfg->prop_count].key, key, MAX_KEY_LEN - 1);
    cfg->props[cfg->prop_count].key[MAX_KEY_LEN - 1] = '\0';
    strncpy(cfg->props[cfg->prop_count].value, value, MAX_VAL_LEN - 1);
    cfg->props[cfg->prop_count].value[MAX_VAL_LEN - 1] = '\0';
    cfg->prop_count++;
    return 0;
}

/* Parse dotted path: rejects __proto__ traversal to prevent prototype pollution */
int set_nested_property(container_config_t *cfg, const char *path, const char *value) {
    if (!cfg || !path || !value) return -1;

    char path_buf[MAX_KEY_LEN * 4];
    strncpy(path_buf, path, sizeof(path_buf) - 1);
    path_buf[sizeof(path_buf) - 1] = '\0';

    container_config_t *target = cfg;
    char *saveptr;
    char *token = strtok_r(path_buf, ".", &saveptr);
    char *next_token = strtok_r(NULL, ".", &saveptr);

    while (next_token != NULL) {
        if (strcmp(token, "__proto__") == 0 ||
            strcmp(token, "prototype") == 0 ||
            strcmp(token, "constructor") == 0) {
            return -1;  /* Reject prototype chain traversal */
        }
        token = next_token;
        next_token = strtok_r(NULL, ".", &saveptr);
    }

    /* Final key also must not be a reserved name */
    if (strcmp(token, "__proto__") == 0 ||
        strcmp(token, "prototype") == 0 ||
        strcmp(token, "constructor") == 0) {
        return -1;
    }

    return set_property(target, token, value);
}

typedef struct {
    int container_id;
    char property_path[MAX_KEY_LEN * 4];
    char value[MAX_VAL_LEN];
} async_task_t;

void* async_set_handler(void *arg) {
    async_task_t *task = (async_task_t *)arg;

    pthread_mutex_lock(&g_orch.lock);
    if (task->container_id >= 0 && task->container_id < g_orch.count) {
        container_config_t *cfg = g_orch.configs[task->container_id];
        set_nested_property(cfg, task->property_path, task->value);
    }
    pthread_mutex_unlock(&g_orch.lock);

    free(task);
    return NULL;
}

int create_container(void) {
    pthread_mutex_lock(&g_orch.lock);
    if (g_orch.count >= MAX_CONTAINERS) {
        pthread_mutex_unlock(&g_orch.lock);
        return -1;
    }
    container_config_t *cfg = calloc(1, sizeof(container_config_t));
    if (!cfg) {
        pthread_mutex_unlock(&g_orch.lock);
        return -1;
    }
    cfg->prototype = &g_orch.base_template;
    int id = g_orch.count;
    g_orch.configs[g_orch.count++] = cfg;
    pthread_mutex_unlock(&g_orch.lock);
    return id;
}

int schedule_property_update(int container_id, const char *path, const char *value) {
    if (!path || !value) return -1;
    async_task_t *task = malloc(sizeof(async_task_t));
    if (!task) return -1;
    task->container_id = container_id;
    strncpy(task->property_path, path, sizeof(task->property_path) - 1);
    task->property_path[sizeof(task->property_path) - 1] = '\0';
    strncpy(task->value, value, sizeof(task->value) - 1);
    task->value[sizeof(task->value) - 1] = '\0';

    pthread_t tid;
    if (pthread_create(&tid, NULL, async_set_handler, task) != 0) {
        free(task);
        return -1;
    }
    pthread_detach(tid);
    return 0;
}

int is_container_privileged(int container_id) {
    pthread_mutex_lock(&g_orch.lock);
    if (container_id < 0 || container_id >= g_orch.count) {
        pthread_mutex_unlock(&g_orch.lock);
        return 0;
    }
    const char *val = resolve_property(g_orch.configs[container_id], "privileged");
    int result = (val && strcmp(val, "true") == 0);
    pthread_mutex_unlock(&g_orch.lock);
    return result;
}

int main(void) {
    init_orchestrator();

    int c1 = create_container();
    int c2 = create_container();

    printf("c1 privileged: %d\n", is_container_privileged(c1));
    printf("c2 privileged: %d\n", is_container_privileged(c2));

    /* Attempt to pollute prototype - will be rejected */
    schedule_property_update(c1, "__proto__.privileged", "true");

    usleep(50000);

    /* Containers remain unprivileged - prototype is protected */
    printf("c1 privileged after: %d\n", is_container_privileged(c1));
    printf("c2 privileged after: %d\n", is_container_privileged(c2));

    return 0;
}
